/**
 *
 * DataTableColumnReorder provides a drag handle for reordering DataTable columns.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableColumnReorder
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UseDataTableColumnReorderEvent } from '@primereact/types/headless/datatable';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
/**
 * Defines passthrough(pt) options type in DataTableColumnReorder component.
 */
export type DataTableColumnReorderPassThroughType<E> = PassThroughType<DataTableColumnReorderInstance, E>;
/**
 * Defines passthrough(pt) options of DataTableColumnReorder component.
 */
export interface DataTableColumnReorderPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataTableColumnReorderPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
}
/**
 * Defines valid properties in DataTableColumnReorder component.
 */
export interface DataTableColumnReorderProps extends BaseComponentProps<DataTableColumnReorderInstance, unknown, DataTableColumnReorderPassThrough, 'span'> {
    /**
     * Index of the column for reordering. Not required — the surrounding `<th>` is the actual
     * drag source and drop target; this handle only hints draggability visually.
     * Kept for backward compatibility and potential fine-grained control.
     */
    columnIndex?: number;
}
/**
 * Defines valid state in DataTableColumnReorder component.
 */
export interface DataTableColumnReorderState {
}
/**
 * Defines the methods and properties exposed by DataTableColumnReorder component.
 */
export interface DataTableColumnReorderExposes {
    /**
     * The DataTable component instance.
     */
    datatable: DataTableRootInstance | undefined | null;
}
/**
 * Instance of DataTableColumnReorder component.
 */
export type DataTableColumnReorderInstance = ComponentInstance<DataTableColumnReorderProps, DataTableColumnReorderState, DataTableColumnReorderExposes>;
/**
 * Event re-exported from the headless layer so consumers can import it from the
 * primitive/UI barrel instead of reaching into headless. Mirrors `UseDataTableColumnReorderEvent`.
 */
export interface DataTableColumnReorderEvent extends UseDataTableColumnReorderEvent {
}
